-- ---------------------------------------------------------------------------
-- تحديث قاعدة E3dady_v2 من migration 0013 لـ 0021 مرة واحدة.
-- ملف متجمّع آليًا من ملفات supabase/migrations/0014 … 0021 زي ما هي بالظبط.
-- كله جوه transaction واحدة: يا إما يتطبق كله، يا إما مفيش حاجة تتغير لو حصل خطأ.
-- شغّله مرة واحدة في Supabase → SQL Editor على مشروع E3dady_v2.
-- ---------------------------------------------------------------------------
begin;


-- ===================== 0014_login_rate_limit.sql =====================
-- ============================================================================
-- تقييد محاولات تسجيل الدخول المتكررة (حماية من هجمات التخمين/القوة الغاشمة).
-- البيئة الحالية ما فيهاش Redis، فاستخدمنا جدول بسيط في نفس قاعدة بيانات
-- Supabase بدل عدّاد في الذاكرة (in-memory) — لأن عدّاد الذاكرة مش موثوق في
-- بيئة serverless (كل استدعاء ممكن يروح لنسخة مختلفة من الخادم مفيهاش نفس
-- العدّاد، زي Vercel). الجدول ده بديل عملي يشتغل صح في هذه البيئة، وموثّق هنا
-- إنه يمكن استبداله بـ Redis لاحقًا لو الحمل زاد كتير.
--
-- التصميم: نحسب عدد محاولات الدخول الفاشلة لكل رقم هاتف (identifier) خلال آخر
-- 15 دقيقة. لو وصلت 5 محاولات فاشلة، نمنع أي محاولة جديدة لنفس الرقم لحد ما
-- تنتهي مدة الانتظار (لا نستدعي Supabase Auth إطلاقًا في هذه الحالة، فمفيش
-- فرصة تخمين إضافية ولا إفصاح عن وجود/عدم وجود الحساب). التقييد بيبقى حسب
-- "الحساب" (رقم الهاتف) وليس الـ IP فقط، لأن عناوين IP المُرسَلة من العميل
-- (زي x-forwarded-for) مش موثوقة تمامًا دايمًا كمعرّف وحيد. القفل مؤقت (15
-- دقيقة فقط) ومش دائم، عشان حد خبيث ميقدرش يعمل "denial of service" بقفل
-- حساب شخص تاني للأبد.
create table if not exists login_attempts (
  id bigint generated always as identity primary key,
  identifier text not null,
  success boolean not null,
  created_at timestamptz not null default now()
);

create index if not exists login_attempts_identifier_idx on login_attempts (identifier, created_at desc);

alter table login_attempts enable row level security;
-- مفيش أي policy لـ anon/authenticated على الجدول نفسه؛ الوصول الوحيد المسموح
-- به هو عبر الدالتين الآمنتين تحت (security definer)، فمحدش يقدر يقرأ أو يكتب
-- في الجدول مباشرة من العميل.

create or replace function login_rate_limit_check(p_identifier text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  fail_count int;
  oldest_fail timestamptz;
  window_seconds int := 900; -- 15 دقيقة
  max_fails int := 5;
  retry_after int := 0;
begin
  select count(*), min(created_at) into fail_count, oldest_fail
  from login_attempts
  where identifier = p_identifier
    and success = false
    and created_at > now() - make_interval(secs => window_seconds);

  if fail_count >= max_fails then
    retry_after := greatest(1, window_seconds - extract(epoch from (now() - oldest_fail))::int);
    return jsonb_build_object('allowed', false, 'retry_after_seconds', retry_after);
  end if;

  return jsonb_build_object('allowed', true, 'retry_after_seconds', 0);
end;
$$;

create or replace function login_rate_limit_record(p_identifier text, p_success boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into login_attempts (identifier, success) values (p_identifier, p_success);
  -- تنظيف السجلات القديمة (أكتر من ساعة) عشان الجدول مايكبرش من غير داعي بمرور الوقت.
  delete from login_attempts where created_at < now() - interval '1 hour';
end;
$$;

revoke all on function login_rate_limit_check(text) from public, anon, authenticated;
revoke all on function login_rate_limit_record(text, boolean) from public, anon, authenticated;
-- لازم "anon" يقدر ينادي الدالتين دول لأن فحص/تسجيل محاولة الدخول بيحصل *قبل*
-- ما يكون فيه session (المستخدم لسه بيحاول يسجّل دخول). الدالتين مش بيرجّعوا
-- أي بيانات حساسة (بس allowed/retry_after)، وبيكتبوا سطر واحد بسيط في جدول
-- داخلي مش متاح للقراءة المباشرة، فالمنح ده آمن ومحدود النطاق.
grant execute on function login_rate_limit_check(text) to anon, authenticated;
grant execute on function login_rate_limit_record(text, boolean) to anon, authenticated;


-- ===================== 0015_login_rate_limit_hardening.sql =====================
-- ============================================================================
-- تصحيح: الدالتين login_rate_limit_check و login_rate_limit_record كانتا
-- ممنوحتين لـ anon (أي زائر غير مسجَّل دخول)، لأن فحص/تسجيل محاولة الدخول
-- بيحصل قبل وجود session. المشكلة إن مفتاح anon علني بطبيعته (مكتوب في كل
-- صفحة من صفحات التطبيق)، فأي حد يقدر يستخدمه مباشرة (من غير المرور بكود
-- التطبيق خالص) وينادي login_rate_limit_record برقم هاتف أي حساب و
-- p_success = false خمس مرات متتالية، فيقفل الحساب ده 15 دقيقة — هجوم حجب
-- خدمة (denial of service) ضد أي مستخدم يعرف رقمه بس، من غير ما يحتاج كلمة
-- مروره. وكمان كان بيسمح بتضخيم الجدول بسجلات وهمية.
--
-- الإصلاح: نمنع anon و authenticated من نداء الدالتين تمامًا، ونخليهم يتنادوا
-- فقط بمفتاح service role (اللي موجود على السيرفر بس، مش متاح للعميل أبدًا).
-- كود التطبيق (app/login/actions.ts) بيتغيّر عشان يستخدم createServiceClient()
-- بدل العميل العادي لما ينادي الدالتين دول تحديدًا.
--
-- ملاحظة مهمة (حد معماري، مش حاجة ممكن تتصلح بالكود وحده): حتى بعد الإصلاح ده،
-- أي حد يقدر يستخدم مفتاح anon العلني عشان ينادي Supabase Auth API مباشرة
-- (POST /auth/v1/token?grant_type=password) من غير ما يمر بكود تطبيقنا خالص،
-- وفي الحالة دي تقييدنا هنا مش هيوقفه. الحماية الحقيقية من النوع ده بتيجي من
-- إعدادات Supabase نفسها (Dashboard → Authentication → Attack Protection /
-- Rate Limits، وتفعيل Captcha). تقييدنا هنا طبقة إضافية (defense in depth) على
-- مسار تسجيل الدخول العادي من واجهة التطبيق، مش بديل كامل عن إعدادات Supabase.
revoke execute on function login_rate_limit_check(text) from anon, authenticated;
revoke execute on function login_rate_limit_record(text, boolean) from anon, authenticated;

grant execute on function login_rate_limit_check(text) to service_role;
grant execute on function login_rate_limit_record(text, boolean) to service_role;


-- ===================== 0016_user_hard_delete.sql =====================
-- ============================================================================
-- تمكين حذف الحسابات نهائيًا (وليس بس تعطيلها) من لوحة تحكم المدير العام.
--
-- المشكلة: عمود "id" في profiles مرتبط بـ auth.users بـ "on delete cascade"،
-- فحذف المستخدم من auth.users (عبر supabase.auth.admin.deleteUser) بيحذف صف
-- profiles بتاعه تلقائيًا. لكن أعمدة تانية كتير بترجع لـ profiles(id) كـ "من
-- سجّل/أنشأ/كلّف العملية دي" (مش "بيانات هو نفسه")، وده بيعمل مشكلتين:
--
-- 1) أعمدة زي audit_log.actor_id و notifications.created_by و
--    mass_attendance.recorded_by وغيرها معرَّفة بدون "on delete" صريح، يعني
--    القيمة الافتراضية في Postgres هي NO ACTION — فحذف أي مستخدم شارك كـ
--    "منفّذ" لأي عملية زي دي (كل خادم/أمين خدمة تقريبًا) هيفشل برسالة خطأ من
--    قاعدة البيانات (foreign key violation) بدل ما يتم الحذف فعليًا.
-- 2) حتى لو الحذف نجح لمستخدم مالوش أي سجل من دول، سجل العمليات والمتابعة
--    بتاعة الآخرين (زي "مين سجّل حضور القداس ده؟") كان ممكن يضيع لو الربط كان
--    "on delete cascade" بالغلط بدل ما يفضل السجل موجود.
--
-- الحل: نغيّر كل الأعمدة دي (اللي معناها "مين نفّذ/أنشأ العملية" مش "بيانات
-- صاحبها") لتبقى "on delete set null" — يعني لو اتحذف المستخدم، السجلات التانية
-- (حضور، إشعارات، مسابقات، سجل العمليات...) تفضل موجودة زي ما هي، بس عمود
-- "مين عمل ده" يبقى فاضي (NULL) بدل ما يمنع الحذف أو يمسح السجل نفسه. البيانات
-- الشخصية للمستخدم نفسه (صلاته، قراءاته، حضوره هو، محاولاته في المسابقات) كانت
-- أصلًا "on delete cascade" من قبل، وده يفضل زي ما هو — دي بيانات بتاعته هو،
-- من المنطقي تتمسح لما حسابه يتمسح.
do $$
declare
  cname text;
  spec record;
begin
  for spec in
    select * from (values
      ('profiles', 'created_by'),
      ('bible_reading_plans', 'created_by'),
      ('mass_attendance', 'recorded_by'),
      ('sunday_school_sessions', 'created_by'),
      ('sunday_school_attendance', 'recorded_by'),
      ('symposium_questions', 'assigned_to'),
      ('notifications', 'created_by'),
      ('quizzes', 'created_by'),
      ('quiz_attempts', 'graded_by'),
      ('audit_log', 'actor_id'),
      ('app_settings', 'updated_by')
    ) as t(table_name, column_name)
  loop
    select tc.constraint_name into cname
    from information_schema.table_constraints tc
    join information_schema.key_column_usage kcu
      on tc.constraint_name = kcu.constraint_name and tc.table_schema = kcu.table_schema
    where tc.table_schema = 'public'
      and tc.table_name = spec.table_name
      and tc.constraint_type = 'FOREIGN KEY'
      and kcu.column_name = spec.column_name;

    if cname is not null then
      execute format('alter table %I drop constraint %I', spec.table_name, cname);
    end if;

    execute format(
      'alter table %I add constraint %I foreign key (%I) references profiles(id) on delete set null',
      spec.table_name, spec.table_name || '_' || spec.column_name || '_fkey', spec.column_name
    );
  end loop;
end $$;

-- عمود symposium_question_notes.author_id كان "not null"، فلازم نسمح بـ NULL
-- فيه الأول قبل ما نقدر نحط "on delete set null" عليه (نفس المنطق فوق: نفضل
-- نص الملاحظة موجود، بس نخلي "مين كتبها" يبقى فاضي لو كاتبها اتحذف).
alter table symposium_question_notes alter column author_id drop not null;

do $$
declare
  cname text;
begin
  select tc.constraint_name into cname
  from information_schema.table_constraints tc
  join information_schema.key_column_usage kcu
    on tc.constraint_name = kcu.constraint_name and tc.table_schema = kcu.table_schema
  where tc.table_schema = 'public'
    and tc.table_name = 'symposium_question_notes'
    and tc.constraint_type = 'FOREIGN KEY'
    and kcu.column_name = 'author_id';

  if cname is not null then
    execute format('alter table symposium_question_notes drop constraint %I', cname);
  end if;

  alter table symposium_question_notes
    add constraint symposium_question_notes_author_id_fkey
    foreign key (author_id) references profiles(id) on delete set null;
end $$;

-- للتحقق بعد تشغيل هذا الملف: الاستعلام ده المفروض يرجّع صفر صفوف (يعني مفيش
-- أي عمود تاني بيرجع لـ profiles(id) بدون "on delete" صريح، وبالتالي أي عمود
-- زيه هيمنع حذف أي مستخدم مرتبط بيه):
--   select conrelid::regclass, conname, confdeltype
--   from pg_constraint
--   where confrelid = 'public.profiles'::regclass and confdeltype = 'a';  -- 'a' = NO ACTION


-- ===================== 0017_login_rate_limit_ip_and_reset.sql =====================
-- ============================================================================
-- تحسينان على تقييد محاولات الدخول (migration 0014/0015):
--
-- 1) عدّاد الفشل كان بيفضل متراكم حتى بعد دخول ناجح — يعني لو حد غلط كلمة
--    السر 3 مرات وبعدين دخل صح، والمحاولات التالتة دي لسه محسوبة لو غلط تاني
--    بعد شوية، فبيتقفل أسرع من 5 محاولات فعلية جديدة. دالة جديدة
--    login_rate_limit_clear بتمسح سجل الفشل لمعرّف معيّن بعد نجاح الدخول.
--
-- 2) التقييد كان برقم الهاتف بس. لو حد عنده سكريبت بيجرّب كذا رقم هاتف من نفس
--    الجهاز (مش بالضرورة يعرف كلمة مرور أي حساب)، كل رقم كان بياخد 5 محاولات
--    لوحده. مفيش دالة SQL جديدة لازمة هنا — login_rate_limit_check/record
--    أصلًا بتاخد "p_identifier" كنص عام، فكود التطبيق (app/login/actions.ts)
--    بقى ينادّيهم مرتين: مرة برقم الهاتف، ومرة بمعرّف الـ IP (بصيغة
--    "ip:<address>")، بحد أعلى مختلف ومعقول (أعلى من حد الهاتف) لأن خدام كتير
--    ممكن يكونوا على نفس شبكة الكنيسة فمينفعش نقفلهم كلهم بسهولة بمجرد IP
--    واحد. ملاحظة: عنوان الـ IP بييجي من هيدر x-forwarded-for، وده موثوق بس
--    في بيئة زي Vercel اللي بتحط الهيدر ده بنفسها على حافة الشبكة (edge) —
--    مش قيمة ممرَّرة من المتصفح مباشرة.
create or replace function login_rate_limit_clear(p_identifier text) returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from login_attempts where identifier = p_identifier and success = false;
end;
$$;

revoke all on function login_rate_limit_clear(text) from public, anon, authenticated;
grant execute on function login_rate_limit_clear(text) to service_role;

-- إعادة تعريف login_rate_limit_check بمعامل اختياري "p_max_fails" (افتراضيًا 5،
-- زي ما كان قبل كده بالظبط) عشان نقدر نستخدم حد أعلى لتقييد الـ IP. ملاحظة
-- مهمة: "create or replace" بيستبدل الدالة فقط لو نفس الاسم ونفس أنواع
-- المعاملات بالظبط؛ إضافة معامل جديد بتعتبره Postgres دالة "overload" منفصلة،
-- فكانت هتفضل الدالة القديمة (نسخة بمعامل واحد) موجودة جنب الجديدة، وده ممكن
-- يلخبط PostgREST في تحديد أي نسخة ينادي لما العميل يبعت p_identifier بس. عشان
-- كده بنشيل النسخة القديمة بمعامل واحد صراحةً الأول.
drop function if exists login_rate_limit_check(text);

create or replace function login_rate_limit_check(p_identifier text, p_max_fails int default 5) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  fail_count int;
  oldest_fail timestamptz;
  window_seconds int := 900; -- 15 دقيقة
  retry_after int := 0;
begin
  select count(*), min(created_at) into fail_count, oldest_fail
  from login_attempts
  where identifier = p_identifier
    and success = false
    and created_at > now() - make_interval(secs => window_seconds);

  if fail_count >= p_max_fails then
    retry_after := greatest(1, window_seconds - extract(epoch from (now() - oldest_fail))::int);
    return jsonb_build_object('allowed', false, 'retry_after_seconds', retry_after);
  end if;

  return jsonb_build_object('allowed', true, 'retry_after_seconds', 0);
end;
$$;

revoke all on function login_rate_limit_check(text, int) from public, anon, authenticated;
grant execute on function login_rate_limit_check(text, int) to service_role;


-- ===================== 0018_audit_log_retention.sql =====================
-- ---------------------------------------------------------------------------
-- 0018: تقليم سجل العمليات (audit_log) تلقائيًا عشان الجدول ميكبرش من غير حد.
-- ---------------------------------------------------------------------------
-- السجل ده مفيد للمحاسبة (من عمل ايه وإمتى)، لكن من غير تقليم هيفضل يكبر للأبد.
-- بدل ما نعتمد على cron خارجي (معندناش واحد في المشروع ده)، بنعمل trigger بسيط:
-- بعد كل إدراج، باحتمال 2% بس (عشان منعملش DELETE مع كل سطر وده بيبقى تكلفة
-- زيادة من غير داعي) نمسح أي سجل أقدم من 180 يوم. النتيجة: الجدول بيفضل محتوي
-- آخر 6 شهور تقريبًا بس، من غير أي صيانة يدوية.
create or replace function audit_log_prune() returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if random() < 0.02 then
    delete from audit_log where created_at < now() - interval '180 days';
  end if;
  return null;
end;
$$;

drop trigger if exists trg_audit_log_prune on audit_log;
create trigger trg_audit_log_prune
  after insert on audit_log
  for each statement
  execute function audit_log_prune();


-- ===================== 0019_prayer_sections.sql =====================
-- ---------------------------------------------------------------------------
-- 0019: تقسيم كل صلاة من الأجبية لأجزاء (الصلاة الربانية، صلاة الشكر، المزامير،
-- الإنجيل، القطع، التحليل...). الولد بيختار الساعة، بعدين الجزء اللي يبدأ منه،
-- وبيتنقل بين الأجزاء بالسحب يمين وشمال.
--
-- نصوص الصلوات نفسها لازم تكون منقولة من مصدر كنسي معتمد (مش متولّدة بالذكاء
-- الاصطناعي) — راجع 0020 للمصدر وطريقة النقل.
-- ---------------------------------------------------------------------------

create table if not exists prayer_sections (
  id uuid primary key default gen_random_uuid(),
  prayer_content_id uuid not null references prayer_contents(id) on delete cascade,
  sort_order smallint not null,
  title_ar text not null,
  body_ar text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (prayer_content_id, sort_order)
);

drop trigger if exists trg_prayer_sections_updated_at on prayer_sections;
create trigger trg_prayer_sections_updated_at
  before update on prayer_sections
  for each row execute function set_updated_at();

alter table prayer_sections enable row level security;

-- القراءة: أي مستخدم مسجّل، لأجزاء الصلوات المفعّلة بس (نفس قاعدة prayer_contents).
drop policy if exists prayer_sections_select on prayer_sections;
create policy prayer_sections_select on prayer_sections for select
  using (
    auth.uid() is not null
    and exists (select 1 from prayer_contents p where p.id = prayer_content_id and p.is_active)
  );

-- الإدارة: كل الأدوار الخادمة (زي محتوى الصلاة في 0011).
drop policy if exists prayer_sections_staff_write on prayer_sections;
create policy prayer_sections_staff_write on prayer_sections for all
  using (auth_role() <> 'member') with check (auth_role() <> 'member');


-- ===================== 0020_seed_agpeya_hours.sql =====================
-- ---------------------------------------------------------------------------
-- 0020: نصوص صلوات باكر والساعة الثالثة والسادسة والتاسعة، مقسّمة لأجزاء.
--
-- المصدر: الأجبية العربية على موقع كنيسة الأنبا تكلا هيمانوت (st-takla.org):
--   https://st-takla.org/Agpeya/Agbeya_01_Prime_.html
--   https://st-takla.org/Agpeya/Agbeya_03_Terce_.html
--   https://st-takla.org/Agpeya/Agbeya_06_Sext_.html
--   https://st-takla.org/Agpeya/Agbeya_09_None_.html
-- النص اتنقل آليًا من الصفحات دي من غير أي تعديل في الكلمات أو التشكيل: اتشالت وسوم
-- HTML بس، واتشال النطق القبطي المكتوب بحروف لاتيني (بخط قبطي مش متاح في التطبيق)،
-- مع الإبقاء على النطق العربي والترجمة. اتأكدنا إن تسلسل كل الحروف العربية مطابق
-- للمصدر حرف بحرف. الملف ده متولّد بسكربت — لا يُعدّل يدويًا.
-- ---------------------------------------------------------------------------

-- matins: 38 جزء
insert into prayer_sections (prayer_content_id, sort_order, title_ar, body_ar)
select p.id, v.sort_order, v.title_ar, v.body_ar from prayer_contents p
cross join (values
  (1, $agpeya$مقدمة كل ساعة$agpeya$, $agpeya$باسم الآب والابن والروح القدس
الإله الواحد آمين.
يا رب ارحم. يا رب ارحم. يا رب بارك. آمين.
المجد للآب والابن والروح القدس الآن وكل أوان وإلى دهر الدهور آمين.$agpeya$),
  (2, $agpeya$الصلاة الربانية$agpeya$, $agpeya$اللهم اجعلنا مستحقين أن نقول بشكر:
أبانا الذي في السموات. ليتقدس اسمك. ليأت ملكوتك. لتكن مشيئتك. كما في السماء كذلك على الأرض. خبزنا الذي للغد أعطنا اليوم. وأغفر لنا ذنوبنا كما نغفر نحن أيضا للمذنبين إلينا. ولا تدخلنا في تجربة. لكن نجنا من الشرير. بالمسيح يسوع ربنا لأن لك الملك والقوة والمجد إلى الأبد. آمين.$agpeya$),
  (3, $agpeya$صلاة الشكر$agpeya$, $agpeya$فلنشكر صانع الخيرات الرحوم الله، أبا ربنا وإلهنا ومخلصنا يسوع المسيح، لأنه سترنا وأعاننا، وحفظنا، وقبلنا إليه وأشفق علينا وعضدنا، وأتى بنا إلى هذه الساعة. هو أيضا فلنسأله أن يحفظنا في هذا اليوم المقدس وكل أيام حياتنا بكل سلام. الضابط الكل الرب إلهنا.
أيها السيد الإله ضابط الكل أبو ربنا وإلهنا ومخلصنا يسوع المسيح، نشكرك على كل حال ومن أجل كل حال، وفى كل حال، لأنك سترتنا، وأعنتنا، وحفظتنا، وقبلتنا إليك، وأشفقت علينا، وعضدتنا، وأتيت بنا إلى هذه الساعة.
من أجل هذا نسأل ونطلب من صلاحك يا محب البشر، امنحنا أن نكمل هذا اليوم المقدس وكل أيام حياتنا بكل سلام مع خوفك. كل حسد، وكل تجربة وكل فعل الشيطان ومؤامرة الناس الأشرار، وقيام الأعداء الخفيين والظاهريين، انزعها عنا وعن سائر شعبك، وعن موضعك المقدس هذا. أما الصالحات والنافعات فارزقنا إياها. لأنك أنت الذي أعطيتنا السلطان أن ندوس الحيات والعقارب وكل قوة العدو. ولا تدخلنا في تجربة، لكن نجنا من الشرير.
بالنعمة والرأفات ومحبة البشر اللواتي لابنك الوحيد ربنا وإلهنا ومخلصنا يسوع المسيح. هذا الذي من قبله المجد والإكرام والعزة والسجود تليق بك معه مع الروح القدس المحيي المساوي لك الآن وكل أوان وإلى دهر الدهور آمين.$agpeya$),
  (4, $agpeya$المزمور الخمسون$agpeya$, $agpeya$ارحمني يا الله كعظيم رحمتك، ومثل كثرة رأفتك تمحو إثمي. اغسلني كثيرا من إثمي ومن خطيتي طهرني، لأني أنا عارف بإثمي وخطيتي أمامي في كل حين. لك وحدك أخطأت، والشر قدامك صنعت. لكي تتبرر في أقوالك. وتغلب إذا حوكمتُ. لأني هاأنذا بالإثم حبل بي، وبالخطايا ولدتني أمي. لأنك هكذا قد أحببت الحق، إذ أوضحت لي غوامض حكمتك ومستوراتها. تنضح على بزوفاك فأطهر، تغسلني فأبيض أكثر من الثلج. تسمعني سرورا وفرحا، فتبتهج عظامي المنسحقة. اصرف وجهك عن خطاياي، وامح كل آثامي. قلبا نقيا اخلق في يا الله، وروحا مستقيما جدده في أحشائي. لا تطرحني من قدام وجهك وروحك القدوس لا تنزعه منى. امنحني بهجة خلاصك، وبروح رئاسي عضدني فأعلم الأثمة طرقك والمنافقون إليك يرجعون، نجني من الدماء يا الله إله خلاصي، فيبتهج لساني بعدلك. يا رب افتح شفتي، فيخبر فمي بتسبيحك. لأنك لو آثرت الذبيحة لكنت الآن أعطي، ولكنك لا تسر بالمحرقات، فالذبيحة لله روح منسحق. القلب المنكسر والمتواضع لا يرذله الله، أنعم يا رب بمسرتك على صهيون، ولتبن أسوار أورشليم. حينئذ تسر بذبائح البر قربانا ومحرقات ويقربون على مذابحك العجول. هلليلويا.$agpeya$),
  (5, $agpeya$هلم نسجد$agpeya$, $agpeya$هلم نسجد هلم نسأل المسيح إلهنا. هلم نسجد، هلم نطلب من المسيح ملكنا. هلم نسجد، هلم نتضرع إلى المسيح مخلصنا. يا ربنا يسوع المسيح كلمة الله إلهنا، بشفاعة القديسة مريم وجميع قديسيك، احفظنا ولنبدأ بدءا حسنا. ارحمنا كإرادتك إلى الأبد. الليل عبر، نشكرك يا رب ونسأل أن تحفظنا في هذا اليوم بغير خطية وأنقذنا.$agpeya$),
  (6, $agpeya$البولس من رسالة أفسس (4: 1-5)$agpeya$, $agpeya$أسألكم أنا الأسير في الرب أن تسلكوا كما يحق للدعوة التي دعيتم إليها، بكل تواضع القلب والوداعة وطول الأناة، محتملين بعضكم بعضا بالمحبة، مسرعين إلى حفظ وحدانية الروح برباط الصلح الكامل لكي تكونوا جسدًا واحدًا وروحًا واحدا، كما دعيتم في رجاء دعوتكم الواحد. ربٍّ واحد. وإيمان واحد. ومعمودية واحدة.$agpeya$),
  (7, $agpeya$من إيمان الكنيسة$agpeya$, $agpeya$واحد هو الله أبو كل أحد. واحد هو أيضا ابنه يسوع المسيح الكلمة، الذي تجسد ومات وقام من الأموات في اليوم الثالث وأقامنا معه، واحد هو الروح القدس المعزى الواحد بأقنومه، منبثق من الآب، يطهر كل البرية. يعلمنا أن نسجد للثالوث القدوس بلاهوت واحد وطبيعة واحدة، نسبحه ونباركه إلى الأبد. آمين.$agpeya$),
  (8, $agpeya$بدء صلاة باكر$agpeya$, $agpeya$صلاة باكر من النهار المبارك، أقدمها للمسيح ملكي وإلهي، وأرجوه أن يغفر لي خطاياي.
من مزامير معلمنا داود النبي بركاته علينا أمين.$agpeya$),
  (9, $agpeya$(1) المزمور الأول$agpeya$, $agpeya$طوبى للرجل الذي لم يسلك في مشورة المنافقين. وفى طريق الخطاة لم يقف، وفى مجلس المستهزئين لم يجلس. لكن في ناموس الرب إرادته، وفى ناموسه يلهج نهارا وليلا. فيكون كالشجرة المغروسة على مجارى المياه التي تعطى ثمرها في حينه. وورقها لا ينتثر، وكل ما يصنع ينجح فيه. ليس كذلك المنافقون، ليس كذلك. لكنهم كالهباء الذي تذريه الريح عن وجه الأرض. فلهذا لا يقوم المنافقون في الدينونة، ولا الخطاة في مجمع الصديقين. لأن الرب يعرف طريق الأبرار، وأما طريق المنافقين فتباد. هلليلويا.$agpeya$),
  (10, $agpeya$(2) المزمور الثاني$agpeya$, $agpeya$لماذا ارتجت الأمم، وتفكرت الشعوب في الباطل. قام ملوك الأرض وتآمر الرؤساء معا على الرب وعلى مسيحه قائلين: لنقطع أغلالهما، ولنطرح عنا نيرهما. الساكن في السموات يضحك بهم، والرب يستهزئ بهم. حينئذ يكلمهم بغضبه، وبرجزه يرجفهم. أنا أقمته ملكا على صهيون جبل قدسه، لأكرز بأمر الرب. الرب قال لي: أنت ابني، وأنا اليوم ولدتك. اسألني فأعطيك الأمم ميراثك، وسلطانك إلى أقطار الأرض. لترعاهم بقضيب من حديد. ومثل آنية الفخار تسحقهم.
فالآن أيها الملوك افهموا، وتأدبوا يا جميع قضاة الأرض اعبدوا الرب بخشية. وهللوا له برعدة. الزموا الأدب لئلا يغضب الرب فتضلوا عن طريق الحق. عندما يتقد غضبه بسرعة، طوبى لجميع المتكلين عليه هلليلويا.$agpeya$),
  (11, $agpeya$(3) المزمور الثالث$agpeya$, $agpeya$يا رب لماذا كثر الذين يحزنونني، كثيرون قاموا علي. كثيرون يقولون لنفسي، ليس له خلاص بإلهه. أنت يا رب أنت هو ناصري، مجدي ورافع رأسي. بصوتي إلى الرب صرخت. فاستجاب لي من جبل قدسه.
أنا اضطجعت ونمت، ثم استيقظت لأن الرب ناصري. فلا أخاف من ربوات الجموع المحيطين بي القائمين على. قم يا رب خلصني يا إلهي، لأنك ضربت كل من يعاديني باطلا. أسنان الخطاة سحقتها. للرب الخلاص وعلى شعبه بركته. هلليلويا.$agpeya$),
  (12, $agpeya$(4) المزمور الرابع$agpeya$, $agpeya$إذ دعوتُ استجبتَ لي يا إله بري. في الشدة فرجت عنى. تراءف على يا رب واسمع صلاتي.
يا بني البشر، حتى متى تثقل قلوبكم؟ لماذا تحبون الباطل وتبتغون الكذب؟ اعلموا أن الرب قد جعل صفيه عجبا. الرب يستجيب لي إذا ما صرخت إليه. اغضبوا ولا تخطئوا، الذي تقولونه في قلوبكم اندموا عليه في مضاجعكم. اذبحوا ذبيحة البر، وتوكلوا على الرب.
كثيرون يقولون: من يرينا الخيرات؟ قد أضاء علينا نور وجهك يا رب. أعطيت سرورا لقلبي أوفر من الذين كثرت حنطتهم وخمرهم وزيتهم. فبالسلامة أضطجع أيضا وأنام، لأنك أنت وحدك يا رب أسكنتني على الرجاء هلليلويا.$agpeya$),
  (13, $agpeya$(5) المزمور الخامس$agpeya$, $agpeya$أنصت يا رب لكلماتي، واسمع صراخي. أصغ إلى صوت طلبتي يا ملكي وإلهي، لأني إليك أصلى. يا رب بالغداة تسمع صوتي، بالغداة أقف أمامك وتراني.
لأنك إله لا تشاء الإثم، ولا يساكنك من يصنع الشر. ولا يثبت مخالفو الناموس أمام عينيك. يا رب أبغضت جميع فاعلي الإثم، وتهلك كل الناطقين بالكذب. رجل الدماء والغاش يرذله الرب. أما أنا فبكثرة رحمتك أدخل بيتك، وأسجد قدام هيكل قدسك بمخافتك.
اهدني يا رب ببرك. من أجل أعدائي سهل أمامي طريقك. لأن ليس في أفواههم صدق. باطل هو قلبهم. حنجرتهم قبر مفتوح. وبألسنتهم قد غشوا. فدنهم يا لله. وليسقطوا من جميع مؤامراتهم وككثرة نفاقهم استأصلهم، لأنهم قد أغضبوك يا رب.
وليفرح جميع المتكلين عليك، إلى الأبد يسرون وتحل فيهم. ويفتخر بك كل الذين يحبون اسمك. لأنك أنت باركت الصديق يا رب. كما بترس المسرة كللتنا. هلليلويا.$agpeya$),
  (14, $agpeya$(6) المزمور السادس$agpeya$, $agpeya$يا رب لا تبكتني بغضبك، ولا تؤدبني بسخطك. ارحمني يا رب فإني ضعيف، اشفني يا رب فإن عظامي قد اضطربت ونفسي قد انزعجت جدا. وأنت يا رب فإلي متى؟ عد ونج نفسي، وأحيني من أجل رحمتك. لأنه ليس في الموت من يذكرك ولا في الجحيم من يعترف لك. تعبت في تنهدي. أعوم كل ليلة سريري، وبدموعي أبل فراشي. تعكرت من الغضب عيناي. شاخت من سائر أعدائي .
ابعدوا عنى يا جميع فاعلي الإثم. لأن الرب قد سمع صوت بكائي. الرب سمع تضرعي، الرب لصلاتي قبل، فليَخزَ وليضطرب جدا جميع أعدائي، وليرتدوا إلى ورائهم بالخزي سريعا جدا. هلليلويا.$agpeya$),
  (15, $agpeya$(7) المزمور الثامن$agpeya$, $agpeya$أيها الرب ربنا، ما أعجب اسمك في الأرض كلها! لأنه قد ارتفع عظم جلالك فوق السموات. من أفواه الأطفال والرضعان هيأت سبحا، من أجل أعدائك، لتسكت عدوا ومنتقما.
لأني أرى السموات أعمال أصابعك. القمر والنجوم أنت أسستها. من هو الإنسان حتى تذكره، أو ابن الإنسان حتى تفتقده؟! أنقصته قليلا عن الملائكة. بالمجد والكرامة توجته، وعلى أعمال يديك أقمته. كل شيء أخضعت تحت قدميه، الغنم والبقر جميعا وأيضا بهائم الحقل، وطيور السماء وأسماك البحر السالكة في البحار. أيها الرب ربنا. ما أعجب اسمك في الأرض كلها. هلليلويا.$agpeya$),
  (16, $agpeya$(8) المزمور الحادي عشر$agpeya$, $agpeya$خلصني يا رب فإن البار قد فني، وقد قلت الأمانة من بنى البشر. تكلم كل واحد مع قريبه بالأباطيل. شفاه غاشة في قلوبهم وبقلوبهم تخاطبوا. يستأصل الرب جميع الشفاه الغاشة، واللسانَ الناطق بالعظائم. الذين قالوا: نعظم ألسنتنا شفاهنا معنا، فمن هو رب علينا؟!
من أجل شقاء المساكين وتنهد البائسين الآن أقوم، يقول الرب، أصنع الخلاص علانية. كلام الرب كلام نقي، فضة محماة مجربة في الأرض، قد صفيت سبعة أضعاف. وأنت يا رب تنجينا وتحفظنا من هذا الجيل وإلى الدهر. المنافقون حولنا يمشون. مثل ارتفاعك أكثرت أعمار بنى البشر. هلليلويا.$agpeya$),
  (17, $agpeya$(9) المزمور الثاني عشر$agpeya$, $agpeya$إلى متى يا رب تنساني؟ إلى الانقضاء؟ حتى متى تصرف وجهك عني؟ إلى متى أردد هذه المشورات في نفسي، وهذه الأوجاع في قلبي النهار كله؟ إلى متى يرتفع عدوى علي؟ انظر واستجب لي يا ربي وإلهي. أنر عيني لئلا أنام نوم الموت، لئلا يقول عدوي: إني قد قويت عليه. الذين يحزنونني يتهللون إن أنا زللت. أما أنا فعلى رحمتك توكلت. يبتهج قلبي بخلاصك. أسبح الرب المحسنَ إلي، وأرتل لاسم الرب العلي. هلليلويا.$agpeya$),
  (18, $agpeya$(10) المزمور الرابع عشر$agpeya$, $agpeya$يا رب من يسكن في مسكنك، ومن يحل في جبل قدسك؟ السالك بلا عيب والفاعل البر، والمتكلم بالحق في قلبه، الذي لا يغش بلسانه، ولا يصنع بقريبه سوءا، ولا يقبل عارا على جيرانه. فاعل الشر مرذول أمامه، ويمجد الذين يتقون الرب. الذي يحلف لقريبه ولا يغدر به. ولا يعطى فضته بالربا، ولا يقبل الرشوة على الأبرياء. الذي يصنع هذا لا يتزعزع إلى الأبد. هلليلويا.$agpeya$),
  (19, $agpeya$(11) المزمور الخامس عشر$agpeya$, $agpeya$احفظني يا رب فإني عليك توكلت. قلت للرب: أنت ربي، ولا تحتاج إلى صلاحي. أظهر عجائبه لقديسيه الذين في أرضه، وصنع فيهم كل مشيئاته. كثرت أمراضهم الذين أسرعوا وراء آخر. لا أجمع مجامعهم من الدماء، ولا أذكر أسماءهم بشفتي. الرب هو نصيب ميراثي وكأسي. أنت الذي ترد إلى ميراثي. حبال المساحة وقعت لي في أرض خصبة، وإن ميراثي لثابت لي.
أبارك الرب الذي أفهمني. وأيضا إلى الليل تنذرني كليتاي. تقدمت فرأيت الرب أمامي في كل حين، لأنه عن يميني لكي لا أتزعزع. من أجل هذا فرح قلبي وتهلل لساني. وأيضا جسدي يسكن على الرجاء. لأنك لا تترك نفسي في الجحيم. ولا تدع قدوسك يرى فسادا. قد عرفتني سبل الحياة. تملأني فرحا مع وجهك. البهجة في يمينك إلى الانقضاء. هلليلويا.$agpeya$),
  (20, $agpeya$(12) المزمور الثامن عشر$agpeya$, $agpeya$السموات تحدث بمجد الله، والفلك يخبر بعمل يديه. يوم إلى يوم يبدي قولا. وليل إلى ليل يظهر علما. لا قول ولا كلام. لا تسمع أصواتهم، في كل الأرض خرج منطقهم. وإلى أقصى المسكونة بلغت أقوالهم. جعل في الشمس مظلته. وهى مثل العريس الخارج من خدره. تتهلل مثل الجبار الذي يسرع في طريقه. من أقصى السماء خروجها، ومنتهاها إلى أقصى السماء ولا شيء يختفي من حرارتها.
ناموس الرب بلا عيب، يرد النفوس. شهادة الرب صادقة، تعلم الأطفال. فرائض الرب مستقيمة، تفرح القلب. وصية الرب مضيئة، تنير العينين عن بعد. خشية الرب زكية، دائمة إلى أبد الأبد. أحكام الرب أحكام حق وعادلة معا. شهوة قلبه مختارة. أفضل من الذهب والحجر الكثير الثمن، وأحلى من العسل والشهد. عبدك يحفظها، وفى حفظها ثواب عظيم. الهفوات من يشعر بها؟ من الخطايا المستترة يا رب طهرني، ومن الغرباء احفظ عبدك حتى لا يتسلطوا على، فحينئذ أكون بلا عيب، وأتنقى من خطية عظيمة. وتكون جميع أقوال فمي وفكر قلبي مرضية أمامك في كل حين. يا رب أنت معيني ومخلصي. هلليلويا.$agpeya$),
  (21, $agpeya$(13) المزمور الرابع والعشرون$agpeya$, $agpeya$إليك يا رب رفعت نفسي، يا إلهي عليك توكلت. فلا تخزني إلى الأبد، ولا تشْمت بي أعدائي. لأن جميع الذين ينتظرونك لا يخزون. ليخز الذين يصنعون الإثم باطلا. أظهر لي يا رب طرقك، وعلمني سبلك. اهدني إلى عدلك وعلمني. لأنك أنت هو الله مخلصي، وإياك انتظرت النهار كله. اذكر يا رب رأفاتك ومراحمك، لأنها ثابتة منذ الأزل. خطايا شبابي وجهالاتي لا تذكر. كرحمتك اذكرني أنت من أجل صلاحك يا رب.
الرب صالح ومستقيم، لذلك يرشد الذين يخطئون في الطريق. يهدى الودعاء في الحكم، يعلم الودعاء طرقه. جميع طرق الرب رحمة وحق لحافظي عهده وشهاداته. من أجل اسمك يا رب اغفر لي خطيتي لأنها كثيرة. من هو الإنسان الخائف الرب، يرشده في الطريق التي ارتضاها. نفسه في الخيرات تثبت، ونسله يرث الأرض. الرب عز لخائفيه، واسم الرب لأتقيائه. ولهم يعلن عهده. عيناي تنظران إلى الرب في كل حين، لأنه يجتذب من الفخ رجلي.
انظر إلى وارحمني، لأني ابن وحيد وفقير أنا. أحزان قلبي قد كثرت، أخرجني من شدائدي. انظر إلى ذلي وتعبي. واغفر لي جميع خطاياي. انظر إلى أعدائي فإنهم قد كثروا وأبغضوني ظلما. احفظ نفسي ونجني، لا أخزى لأني عليك توكلت. الذين لا شر فيهم والمستقيمون لصقوا بي، لأني انتظرتك يا رب. يا الله أنقذ إسرائيل من جميع شدائده. هلليلويا.$agpeya$),
  (22, $agpeya$(14) المزمور السادس والعشرون$agpeya$, $agpeya$الرب نوري وخلاصي ممن أخاف؟! الرب حصن حياتي ممن أجزع؟! عندما يقترب الأشرار منى ليأكلوا لحمي، مضايقي وأعدائي عثروا وسقطوا. إن يحاربني جيش فلن يخاف قلبي. وإن قام على قتال ففي هذا أنا أطمئن. واحدة سألت من الرب وإياها ألتمس. أن أسكن في بيت الرب كلَّ أيام حياتي. لكي أنظر نعيم الرب، وأتفرس في هيكله المقدس. لأنه أخفاني في خيمته. في يوم شدتي، سترني بستر مظلته. وعلى صخرة رفعني. والآن هوذا قد رفع رأسي على أعدائي. طفت وذبحت في مظلته ذبيحة التهليل، أسبح وأرتل للرب.
استمع يا رب صوتي الذي به دعوتك. ارحمني واستجب لي فإنه لك قال قلبي: طلبت وجهك، ووجهك يا رب ألتمس. لا تحجب وجهك عنى، ولا تنبذ بغضبك عبدك. كن لي معينا، لا تخذلني ولا ترفضني يا الله مخلصي. فإن أبى وأمي قد تركاني، وأما الرب فقبلني. علمني يا رب طريقك، واهدني في سبيل مستقيم من أجل أعدائي. لا تسلمني إلى أيدي مضايقي، لأنه قد قام على شهود زور، وكذبوا علي ظلما. وأنا أؤمن أنى أعاين خيرات الرب في أرض الأحياء. انتظر الربّ، تقوَّ وليتشدد قلبك وانتظر الرب. هلليلويا.$agpeya$),
  (23, $agpeya$(15) المزمور الثاني والستون$agpeya$, $agpeya$يا الله إلهي إليك أبكر، عطشت إليك نفسي. يشتاق إليك جسدي، في أرض مقفرة وموضع غير مسلوك ومكان بلا ماء. هكذا ظهرت لك في القدس، لأرى قوّتك ومجدك. لان رحمتك أفضل من الحياة. شفتاي تسبحانِك. لذلك أباركك في حياتي، وباسمك أرفع يدي. فتشبع نفسي كما من شحم ودسم. بشفاه الابتهاج نبارك اسمك. كنت أذكرك على فراشي، وفى أوقات الأسحار كنت أرتل لك. لأنك صرت لي عونا، وبظل جناحيك أبتهج.
التحقت نفسي وراءك، ويمينك عضدتني. أما الذين طلبوا نفسي للهلاك، فيدخلون في أسافل الأرض. ويُدفعون إلى يد السيف، ويكونون أنصبة للثعالب. أما الملك فيفرح بالله، ويفتخر كل من يحلف به. لأن أفواه المتكلمين بالظلم تُسَدُّ. هلليلويا.$agpeya$),
  (24, $agpeya$(16) المزمور السادس والستون$agpeya$, $agpeya$ليتراءف الله علينا ويباركنا، وليظهر وجهه علينا ويرحمنا. لتعرَف في الأرض طريقك، وفى جميع الأمم خلاصك. فلتعترف لك الشعوب يا الله، فلتعترف لك الشعوب كلها. لتفرح الأمم وتبتهج، لأنك تحكم في الشعوب بالاستقامة، وتهدى الأمم في الأرض. فلتعترف لك الشعوب يا الله، فلتعترف لك الشعوب جميعا. الأرض أعطت ثمرتها، فليباركنا الله إلهنا. ليباركنا الله، فلتخشه جميع أقطار الأرض. هلليلويا.$agpeya$),
  (25, $agpeya$(17) المزمور التاسع والستون$agpeya$, $agpeya$اللهم التفت إلى معونتي، يا رب أسرع وأعنى. ليَخزَ ويخجل طالبو نفسي، وليرتد إلى خلف ويخجل الذين يبتغون لي الشر. وليرجع بالخزي سريعا القائلون لي: نِعِمَّا نِعِمَّا. وليبتهج ويفرح بك جميع الذين يلتمسونك، وليقل في كل حين محبو خلاصك: فليتعظم الرب. وأما أنا فمسكين وفقير، اللهم أعنى. أنت معيني ومخلصي يا رب فلا تبطئ.هلليلويا.$agpeya$),
  (26, $agpeya$(18) المزمور المائة والثاني عشر$agpeya$, $agpeya$سبحوا الرب أيها الفتيان، سبحوا اسم الرب. ليكن اسم الرب مباركا من الآن وإلى الأبد. من مشارق الشمس إلى مغاربها باركوا اسم الرب. الرب عالٍ على كل الأمم، فوق السموات مجده. من مثل الرب إلهنا؟!‍ الساكن في الأعالي، الناظِر إلى المتواضعين في السماء وعلى الأرض. المقيم المسكين من التراب، الرافع البائس من المِزْبَلة لكي يُجلسه مع رؤساء شعبه. الذي يجعل العاقرَ ساكنة في بيت، أم أولادٍ فرحة. هلليلويا.$agpeya$),
  (27, $agpeya$(19) المزمور المائة والثاني والأربعون$agpeya$, $agpeya$يا رب اسمع صلاتي. أنصت إلى طلبتي بحقك. استجب لي بعدلك. ولا تدخل في المحاكمة مع عبدك، فإنه لن يتزكى قدامك كل حي. لأن العدو قد اضطهد نفسي، وأذل في الأرض حياتي. أجلسَني في الظلمات مثل الموتى منذ الدهر، أضجر في روحي، اضطرب في قلبي. تذكرت الأيام الأولى ولهجت في كل أعمالك، وفى صنائع يديك كنت أتأمل. بسطت إليك يدي، صارت نفسي لك مثل أرض بلا ماء.
استجب لي يا رب عاجلا، فقد فنيت روحي. لا تحجب وجهك عني، فأشابه الهابطين في الجب. فلأسمع في الغدوات رحمتك، فإني عليك توكلت. عرفني يا رب الطريق التي أسلك فيها، لأني إليك رفعت نفسي. أنقذني من أعدائي يا رب، فإني لجأت إليك. علمني أن أصنع مشيئتك، لأنك أنت هو إلهي. روحك القدوس فليهدني إلى الاستقامة، من أجل اسمك يا رب تحييني. بحقك تخرج من الشدة نفسي، وبرحمتك تستأصل أعدائي. وتهلك جميع مضايقي نفسي، لأني أنا هو عبدك أنا. هلليلويا.$agpeya$),
  (28, $agpeya$(إنجيل يوحنا 1: 1-17)$agpeya$, $agpeya$من إنجيل معلمنا يوحنا البشير بركاته علينا أمين.
في البدء كان الكلمة، والكلمة كان عندَ الله. وكان الكلمة الله، هذا كان في البدء عند الله. كل شيء به كان، وبغيره لم يكن شيء مما كان. فيه كانت الحياة، والحياة كانت نورَ الناس، والنور أضاء في الظلمة، والظلمة لم تدركه.
كان إنسان مرسل من الله اسمه يوحنا، هذا جاء للشهادة ليشهد للنور ليؤمن الكل بواسطته. لم يكن هو النور بل ليشهد للنور، كان النورُ الحقيقي الذي ينير كل إنسان آتيا إلى العالم. كان في العالم، وكُوِّنَ العالم به، ولم يعرفه العالم. إلى خاصته جاء، وخاصته لم تقبله. وأما الذين قبلوه فأعطاهم سلطانًا أن يصيروا أبناء الله، الذين يؤمنون باسمه، الذين ولدوا ليس من دم، ولا من مشيئة جسد، ولا من مشيئة رجل، لكن من الله ولدوا.
والكلمة صار جسدًا وحل بيننا ورأينا مجده مثل مجد ابن وحيد لأبيه مملوءًا نعمة وحقًا. يوحنا شهد له وصرخ قائلًا: هذا هو الذي قلت عنه إن الذي يأتي بعدى كان قبلي، لأنه كان أقدم منى. ونحن جميعا أخذنا من ملئه، ونعمة عوضًا عن نعمة. لأن الناموس بموسى أعطى. أما النعمة والحق فبيسوع المسيح صارا. والمجد لله دائمًا أبديًا أمين.$agpeya$),
  (29, $agpeya$القطع$agpeya$, $agpeya$أيها النور الحقيقي الذي يضئ لكل إنسان آت إلى العالم، أتيت إلى العالم بمحبتك للبشر، وكل الخليقة تهللت بمجيئك. خلصت أبانا آدم من الغواية، وعتقت أمنا حواء من طلقات الموت، وأعطيتنا روح البنوة، نسبحك ونباركك قائلين: (ذوكصابتري كيه إيو كي آجيو ابنيفماتي - المجد للآب والابن والروح القدس).
إذا ما دخل إلينا وقت الصباح أيها المسيح إلهنا النور الحقيقي، فلتشرق فينا الحواس المضيئة والأفكار النورانية. ولا تغطينا ظلمة الآلام، لكي نسبحك عقليا مع داود قائلين: "سبقت عيناي وقت السحر لأتلو في جميع أقوالك". اسمع أصواتنا كعظيم رحمتك، ونجنا أيها الرب إلهنا بتحننك. (كي نين، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين - الآن وكل أوان وإلى دهر الداهرين آمين)
أنت هي أم النور المكرمة، من مشارق الشمس إلى مغاربها يقدمون لك تمجيدات يا والدة الإله السماء الثانية، لأنك أنت هي الزهرة النيرة غير المتغيرة والأم الباقية عذراء، لأن الآب اختارك، والروح القدس ظللك، والابن تنازل وتجسد منك. فاسأليه أن يعطى الخلاص للعالم الذي خلقه، وأن ينجيَّه من التجارب. نسبحه تسبيحا جديدا ونباركه الآن وكل أوان وإلى الأبد. أمين.$agpeya$),
  (30, $agpeya$تسبحة الملائكة$agpeya$, $agpeya$فلنسبح مع الملائكة قائلين: المجد لله في الأعالي وعلى الأرض السلام وفى الناس المسرة. نسبحك. نباركك. نخدمك. نسجد لك. نعترف لك. ننطق بمجدك. نشكرك من أجل عظم مجدك، أيها الرب المالك على السموات، الله الآب ضابط الكل، والرب الابن الواحد الوحيد يسوع المسيح، والروح القدس.
أيها الرب الإله، حمل الله، ابن الآب، رافع خطية العالم، ارحمنا. يا حامل خطية العالم، اقبل طلباتنا إليك. أيها الجالس عن يمين أبيه، ارحمنا. أنت وحدك القدوس. أنت وحدك العالي يا ربى يسوع المسيح والروح القدس. مجدا لله الآب أمين.
أباركك كل يوم، وأسبح اسمك القدوس إلى الأبد. وإلى أبد الأبد. أمين. منذ الليل روحي تبكر إليك يا إلهي، لأن أوامرك هي نور على الأرض. كنت أتلو في طرقك، لأنك صرت لي معينا. باكرا يا رب تسمع صوتي، بالغداة أقف أمامك وتراني.$agpeya$),
  (31, $agpeya$الثلاث تقديسات$agpeya$, $agpeya$قدوس الله، قدوس القوى، قدوس الحي الذي لا يموت، الذي ولد من العذراء، ارحمنا. قدوس الله، قدوس القوى، قدوس الحي الذي لا يموت، الذي صلب عنا، ارحمنا. قدوس الله، قدوس القوى، قدوس الحي الذي لا يموت، الذي قام من الأموات وصعد إلى السموات، ارحمنا. المجد للآب والابن والروح القدس، الآن وكل أوان وإلى دهر الدهور. أمين. أيها الثالوث القدوس ارحمنا. أيها الثالوث القدوس ارحمنا. أيها الثالوث القدوس ارحمنا.
يا رب اغفر لنا خطايانا. يا رب اغفر لنا آثامنا. يا رب اغفر لنا زلاتنا. يا رب افتقد مرضى شعبك، اشفهم من أجل اسمك القدوس. آباؤنا وإخوتنا الذين رقدوا، يا رب نيح نفوسهم. يا من هو بلا خطية، يا رب ارحمنا. يا من بلا خطية، يا رب أعنا، واقبل طلباتنا إليك. لأن لك المجد والعزة والتقديس المثلث. يا رب ارحم. يا رب ارحم يا رب بارك. أمين.
واجعلنا مستحقين أن نقول بشكر: أبانا الذي في السموات....$agpeya$),
  (32, $agpeya$السلام لك$agpeya$, $agpeya$السلام لك. نسألك أيتها القديسة الممتلئة مجدا العذراء كل حين، والدة الإله أم المسيح، أصعدي صلواتنا إلى ابنك الحبيب ليغفر لنا خطايانا.
السلام للتي ولدت لنا النور الحقيقي المسيح إلهنا، العذراء القديسة، اسألي الرب عنا، ليصنع رحمة مع نفوسنا، ويغفر لنا خطايانا.
أيتها العذراء مريم والدة الإله، القديسة الشفيعة الأمينة لجنس البشرية، اشفعي فينا أمام المسيح الذي ولدته لكي ينعم علينا بغفران خطايانا.
السلام لك أيتها العذراء الملكة الحقيقية، السلام لفخر جنسنا، ولدت لنا عمانوئيل. نسألك: اذكرينا، أيتها الشفيعة المؤتمنة، أمام ربنا يسوع المسيح، ليغفر لنا خطايانا.$agpeya$),
  (33, $agpeya$بدء قانون الإيمان$agpeya$, $agpeya$نعظمك يا أم النور الحقيقي، ونمجدك أيتها العذراء القديسة، والدة الإله، لأنك ولدت لنا مخلص العالم، أتى وخلص نفوسنا.
المجد لكَ يا سيدنا وملكنا المسيح، فخر الرسل، إكليل الشهداء تهليل الصديقين، ثبات الكنائس، غفران الخطايا.
نبشر بالثالوث القدوس، لاهوت واحد، نسجد له ونمجده. يا رب ارحم. يا رب ارحم. يا رب بارك. أمين.$agpeya$),
  (34, $agpeya$قانون الإيمان المقدس الأرثوذكسي$agpeya$, $agpeya$بالحقيقة نؤمن بإله واحد، الله الآب، ضابط الكل، خالق السماء والأرض، ما يُرَى وما لا يرى.
نؤمن برب واحد يسوع المسيح، ابن الله الوحيد، المولود من الآب قبل كل الدهور، نور من نور، إله حق من إله حق، مولود غير مخلوق، مساو للآب في الجوهر، الذي به كان كل شيء. هذا الذي من أجلنا نحن البشر، ومن أجل خلاصنا، نزل من السماء، وتجسد من الروح القدس ومن مريم العذراء، وتأنس. وصلب عنا على عهد بيلاطس البنطي. وتألم وقبر وقام من بين الأموات في اليوم الثالث كما في الكتب، وصعد إلى السموات، وجلس عن يمين أبيه، وأيضا يأتي في مجده ليدين الأحياء والأموات، الذي ليس لملكه انقضاء.
نعم نؤمن بالروح القدس، الرب المحيى المنبثق من الآب. نسجد له ونمجده مع الآب والابن، الناطق في الأنبياء.
وبكنيسة واحدة مقدسة جامعة رسولية.
ونعترف بمعمودية واحدة لمغفرة الخطايا.
وننتظر قيامة الأموات وحياة الدهر الآتي. أمين.
كيرياليسون (يا رب ارحم) 41 مرة$agpeya$),
  (35, $agpeya$قدوس قدوس قدوس$agpeya$, $agpeya$قدوس، قدوس، قدوس، رب الصباؤوت. السماء والأرض مملوءتان من مجدك وكرامتك. ارحمنا يا الله الآب ضابط الكل. أيها الثالوث القدوس ارحمنا. أيها الرب إله القوات كن معنا، لأنه ليس لنا معين في شدائدنا وضيقاتنا سواك.
حل واغفر واصفح لنا يا الله عن سيئاتنا، التي صنعناها بإرادتنا والتي صنعناها بغير إرادتنا، التي فعلناها بمعرفة والتي فعلناها بغير معرفة، الخفية والظاهرة. يا رب اغفرها لنا، من أجل اسمك القدوس الذي دعي علينا. كرحمتك يا رب وليس كخطايانا.
واجعلنا مستحقين أن نقول بشكر: أبانا الذي في السموات..$agpeya$),
  (36, $agpeya$التحليل$agpeya$, $agpeya$أيها الرب إله القوات، الكائن قبل الدهور والدائم إلى الأبد، الذي خلق الشمس لضياء النهار، والليل راحة لكل البشر، نشكرك يا ملك الدهور لأنك أجزتنا هذا الليل بسلام وأتيت بنا إلى مبدأ النهار.
من أجل هذا نسأل يا ملكنا ملك الدهور، ليشرق لنا نور وجهك، وليضيء علينا نور علمك الإلهي. واجعلنا يا سيدنا أن نكون بنى النور وبني النهار، لكي نجوز هذا اليوم ببر وطهارة وتدبير حسن، لنكمل بقية أيام حياتنا بلا عثرة. بالنعمة والرأفة ومحبة البشر اللواتي لابنك الوحيد يسوع المسيح، وموهبة روحك القدوس. الآن وكل أوان وإلى الأبد. أمين.$agpeya$),
  (37, $agpeya$تحليل آخر$agpeya$, $agpeya$أيها الباعث النور فينطلق، المشرق شمسه على الأبرار والأشرار، الذي صنع النور الذي يضئ على المسكونة، أنر عقولنا وقلوبنا وأفهامنا يا سيد الكل. هب لنا في هذا اليوم الحاضر أن نرضيك فيه. واحرسنا من كل شيء رديء ومن كل خطيئة، ومن كل قوة مضادة بالمسيح يسوع ربنا. هذا الذي أنت مبارك معه مع الروح القدس المحيى المساوي لك، الآن وكل أوان وإلى دهر الدهور. أمين.$agpeya$),
  (38, $agpeya$طلبة تصلى آخر كل ساعة$agpeya$, $agpeya$ارحمنا يا الله ثم ارحمنا. يا من في كل وقت وكل ساعة، في السماء وعلى الأرض، مسجود له وممجد. المسيح إلهنا الصالح، الطويل الروح، الكثير الرحمة، الجزيل التحنن، الذي يحب الصديقين ويرحم الخطاة الذين أولهم أنا. الذي لا يشاء موت الخاطئ مثل ما يرجع ويحيا. الداعي الكل إلى الخلاص لأجل الموعد بالخيرات المنتظرة.
يا رب اقبل منا في هذه الساعة وكل ساعة طلباتنا. سهل حياتنا، وأرشدنا إلى العمل بوصاياك. قدس أرواحنا. طهر أجسامنا. قوم أفكارنا. نق نياتنا. اشف أمراضنا واغفر خطايانا. ونجنا من كل حزن رديء ووجع قلب. أحطنا بملائكتك القديسين، لكي نكون بمعسكرهم محفوظين ومرشدين، لنصل إلى اتحاد الإيمان وإلى معرفة مجدك غير المحسوس وغير المحدود، فإنك مبارك إلى الأبد. أمين.
اللهم اجعلنا مستحقين أن نقول بشكر: أبانا الذي في السموات...$agpeya$)
) as v(sort_order, title_ar, body_ar)
