-- نصف الليل بقت 3 صلوات: الخدمة الأولى (الكود القديم midnight) + خدمتين جداد.
update prayer_contents set title_ar = 'صلاة نصف الليل - الخدمة الأولى' where code = 'midnight';
insert into prayer_contents (code, title_ar, body_ar, sort_order, is_active) values
  ('midnight_2', 'صلاة نصف الليل - الخدمة الثانية', '', 8, false),
