-- midnight_3: 22 جزء
insert into prayer_sections (prayer_content_id, sort_order, title_ar, body_ar)
select p.id, v.sort_order, v.title_ar, v.body_ar from prayer_contents p
cross join (values
  (1, $agpeya$بدء الصلاة$agpeya$, $agpeya$تسبحة الخدمة الثالثة من نصف الليل المبارك، أقدمها للمسيح ملكي والهي، وأرجوه أن يغفر لي خطاياي.
تتلى مزامير صلاة النوم كما يلي:$agpeya$),
  (2, $agpeya$(1) المزمور المائة والتاسع والعشرون$agpeya$, $agpeya$من الأعماق صرخت إليك يا رب، يا رب استمع صوتي. لتكن أذناك مصغيتين إلى صوت تضرعي. إن كنت للآثام راصدا يا رب، يا رب من يثبت لأن من عندك المغفرة. من أجل اسمك صبرْتُ لك يا رب، صبرَتْ نفسي لناموسك. انتظرت نفسي الرب من محرس الصبح إلى الليل. من محرس الصبح فلينتظر إسرائيل الرب. لأن الرحمة من عند الرب. عظيم هو خلاصه وهو يفتدي إسرائيل من كل آثامه هلليلويا.$agpeya$),
  (3, $agpeya$(2) المزمور المائة والثلاثون$agpeya$, $agpeya$يا رب لم يرتفع قلبي، ولم تستعلِ عيناي، ولم أسلك في العظائم ولا في العجائب التي هي أعلى مني. فان كنت لم أتضع لكن رفعت صوتي مثل الفطيم من اللبن على أمه، كذلك المجازاة على نفسي. فليتكل إسرائيل على الرب من الآن والى الأبد هلليلويا.$agpeya$),
  (4, $agpeya$(3) المزمور المائة والحادي والثلاثون$agpeya$, $agpeya$اذكر يا رب داود وكل دعته، كيف أقسم للرب ونذر لإله يعقوب: إني لا أدخل إلى مسكن بيتي، ولا أصعد على سرير فراشي، ولا أعطى لعيني نوما، ولا لأجفاني نعاسا، ولا راحة لصدغيَّ، إلى أن أجد موضعا للرب ومسكنا لإله يعقوبَ. ها قد سمعنا به في افراته ووجدناه في موضع الغابة. فلندخل إلى مساكنه ونسجد في الموضع الذي فيه استقرت قدماه.
قم يا رب إلى راحتك أنت وتابوت موضع قدسك. كهنتك يلبسون البر وأبرارك يبتهجون. من أجل داود عبدك لا ترد وجهك عن مسيحك. حلف الرب لداود حقا ولا يخلف: لأجعَلنَّ من ثمرة بطنك على كرسيك. إن حفظ بنوك عهدي وشهاداتي التي أعلمهم إياها، فبنوهم أيضا يجلسون إلى الأبد على كرسيك. لأن الرب اختار صهيون ورضيها مسكننا له. هذا هو موضع راحتي إلى أبد الأبد، ههنا أسكن لأني أردته. لصيدها أبارك بركة، لمساكينها أشبع خبزا، لكهنتها ألبس الخلاص وأبرارها يبتهجون ابتهاجا. هناك أقيم قرنا لداود. هيأتُ سراجا لمسيحي. لأعدائه ألبس الخزي وعليه يزهر قدسي هلليلويا.$agpeya$),
  (5, $agpeya$(4) المزمور المائة والثاني والثلاثون$agpeya$, $agpeya$هوذا ما أحسن وما أحلي أن يسكن الاخوة معا. كالطيب الكائن على الرأس الذي ينزل على اللحية، لحية هارون النازلة على جيب قميصه. ومثل ندى حرمون المنحدر على جبل صهيون. لأن هناك أمر الرب بالبركة والحياة إلى الأبد هلليلويا.$agpeya$),
  (6, $agpeya$(5) المزمور المائة والثالث والثلاثون$agpeya$, $agpeya$ها باركوا الربَّ يا عبيدَ الرب، القائمين في بيت الرب في ديار إلهنا. في الليالي ارفعوا أيديكم إلى القدس وباركوا الرب. يبارككم الرب من صهيون الذي خلق السماء والأرض هلليلويا.$agpeya$),
  (7, $agpeya$(6) المزمور المائة والسادس والثلاثون$agpeya$, $agpeya$على أنهار بابل هناك جلسنا، فبكينا عندما تذكرنا صهيون. على الصفصاف في وسطها علقنا قيثاراتنا، لأنه هناك سألنا الذين سبونا أقوالَ التسبيح. والذين استاقونا إلى هناك قالوا: سبحوا لنا تسبحة من تسابيح صهيون.
كيف نسبِّح تسبحة الرب في أرض غريبة. إن نسيتك يا أورشليم أنسَ يميني، ويلتصق لساني بحنكي إن لم أذكرك، إن لم أفضل أورشليم في ابتداء فرحي.
اذكر يا رب بني أدوم في يوم أورشليم القائلين: انقضوا انقضوا حتى الأساس منها. يا بنت بابل الشقية طوبى لمن يكافئك مكافأتك التي جازيتينا. طوبى لمن يمسك أطفالك ويدفنهم عند الصخرة هلليلويا.$agpeya$),
  (8, $agpeya$(7) المزمور المائة والسابع والثلاثون$agpeya$, $agpeya$أعترف لك يا رب من كل قلبي لأنك استمعت كل كلمات فمي. أمام الملائكة أرتل لك وأسجد قدام هيكلك المقدس، وأعترف لاسمك على رحمتك وحقك، لأنك قد عظمت اسمك القدوس على الكل. اليوم الذي أدعوك فيه أجبني بسرعة. تكثر التطلع على نفسي بقوة.
فليعترف لك يا رب كل ملوك الأرض. لأنهم قد سمعوا سائر كلمات فمك وليسبحوا في طرق الرب. لأن مجد الرب عظيم لأن الرب عال ويعاين المتواضعات والكائنات يعرفها من بعد. إن سلكت في وسط الشدة فإنك تحييني. على رجز الأعداء مددت يدك وخلصتني يمينك. الرب يجازي عني، يا رب رحمتك دائمة إلى الأبد. أعمال يديك يا رب لا تتركها هلليلويا.$agpeya$),
  (9, $agpeya$(8) المزمور المائة والأربعون$agpeya$, $agpeya$يا رب إليك صرخت فاستمع لي. أنصت إلى صوت تضرعي، إذا ما صرختُ إليك. لتستقم صلاتي كالبخور قدامك. وليكن رفع يدي كذبيحة مسائية. ضع يا رب حافظا لفمي، وبابا حصينا لشفتي. ولا تمل قلبي إلى كلام الشر، فيتعلل بعلل في الخطايا مع أناس فاعلي الإثم، ولا أتفق مع مختاريهم. فليؤدبني الصديق برحمة ويوبخني. أما زيت الخاطئ فلا يدهن رأسي، لأن صلاتي أيضا بمسرة. قد ابتُلِع أقوياؤهم عند الصخرة، يسمعون كلماتي لأنهم استلذوا. مثل شحم الأرض انشقوا على الأرض. تبددت عظامهم عند الجحيم، لأن عيوننا إليك يا رب، يا رب عليك توكلت فلا تقتل نفسي. احفظني من الفخ الذي قد نصبوه لي. ومن شكوك فاعلي الإثم. يسقط الخطاة في شبكتهم، وأكون أنا وحدي حتى يجوزَ الإثم هلليلويا$agpeya$),
  (10, $agpeya$(9) المزمور المائة والحادي والأربعون$agpeya$, $agpeya$بصوتي إلى الرب صرختُ، بصوتي إلى الرب تضرعتُ. أسكب أمامه توسلي. أبث لديه ضيقي، عند فناء روحي مني وأنت علمتَ سبلي. في الطريق التي أسلك أخفوا لي فخا، تأملت عن اليمين وأبصرت فلم يكن من يعرفني. ضاع المهرب مني وليس من يسأل عن نفسي. فصرختُ إليك يا رب وقلت: أنت هو رجائي وحظي في أرض الأحياء. أنصت إلى طلبتي فإنني قد تذللتُ جدا. نجني من الذين يضطهدونني لأنهم قد اعتزوا أكثر مني. أخرج من الحبس نفسي، لكي أشكر اسمك يا رب. إياي ينتظر الصديقون حتى تجازيني هلليلويا.$agpeya$),
  (11, $agpeya$(10) المزمور المائة والخامس والأربعون$agpeya$, $agpeya$سبحي يا نفسي الربَّ، أسبح الرب في حياتي وأرتل لإلهي ما دمت موجودا. لا تتكلوا على الرؤساء ولا على بني البشر الذين ليس عندهم خلاص. تخرج روحهم فيعودون إلى ترابهم. في ذلك اليوم تهلك كافة أفكارهم.
طوبى لمن إله يعقوب معينه. واتكاله على الرب إلهه، الذي صنع السماء والأرض والبحر وكل ما فيها. الحافظ العدل إلى الدهر، الصانع الحكم للمظلومين المعطي الطعام للجياع. الرب يحل المربوطين الرب يقيم الساقطين. الرب يُحَكِّم العميان. الرب يحب الصديقين. الرب يحفظ الغرباء، ويعضد اليتيم والأرملة. ويبيد طرق الخطاة. يملك الرب إلى الدهر، وإلهك يا صهيون من جيل إلى جيل هلليلويا .$agpeya$),
  (12, $agpeya$(11) المزمور المائة والسادس والأربعون$agpeya$, $agpeya$سبحوا الرب فان المزمور جيد، ولإلهنا يلذ التسبيح. الرب يبني أورشليم. الرب يجمع متفرقي إسرائيل. الرب يشفي المنكسري القلوب، ويجبر جميع كسرهم. المحصي كثرة الكواكب، ولكافتها يعطي أسماء. عظيم هو الرب وعظيمة هي قوته، ولا إحصاء لفهمه. الرب يرفع الودعاء ويذل الخطاة إلى الأرض.
ابتدئوا للرب بالاعتراف، رتلوا لإلهنا بالقيثارة. الذي يجلل السماء بالغمام، الذي يهيئ للأرض المطر، الذي يُنبت العشب على الجبال، والخضرة لخدمة البشر، ويعطي البهائم طعامها، ولفراخ الغربان التي تدعوه. لا يؤْثر قوة الفرس ولا يسر بساقي الرجل، بل يسر الرب بخائفيه وبالراجين رحمته هلليلويا.$agpeya$),
  (13, $agpeya$(12) المزمور المائة والسابع والأربعون$agpeya$, $agpeya$سبحي الرب يا أورشليم، سبحي إلهك يا صهيون. لأنه قد قوى مغاليق أبوابك وبارك بنيك فيك. الذي جعل تخومَك في سلام، ويملأك من شحم الحنطة. الذي يرسل كلمته إلى الأرض فيسرع قوله عاجلا جدا. المعطي الثلج كالصوف، المذري الضباب كالرماد، ويلقي الجليد مثل الفتات. قدام وجه برْدِه من يقوم. يرسل كلمته فتذيبه، تهب ريحه فتسيل المياه. المخبر كلمته ليعقوب وفرائضه وأحكامه لإسرائيل. لم يصنع هكذا بكل الأمم، وأحكامُه لم يوضحها لهم هلليلويا.$agpeya$),
  (14, $agpeya$(إنجيل لوقا 12: 32-46)$agpeya$, $agpeya$لا تخف أيها القطيع الصغير، فإن أباكم قد سر أن يعطيكم الملكوت. بيعوا أمتعتكم وأعطوا صدقة، واصنعوا لكم أكياسا لا تبلى، وكنزا في السموات لا يفنى، حيث لا يدنو منه سارق ولا يفسده سوس. لأنه حيث يكون كنزكم، هناك يكون قلبكم أيضا. لتكن أحقاؤكم ممنطقة ومصابيحكم موقدة وأنتم أيضا تشبهون أناسا ينتظرون سيدهم، متى يرجع من العرس، حتى إذا جاء وقرع يفتحون له للوقت. طوبى لأولئك العبيد الذين إذا جاء سيدهم يجدهم ساهرين. الحق أقول لكم إنه يتمنطق ويتكئهم ويقوم فيخدمهم. وإذا جاء في الهزيع الثاني أو جاء في الهزيع الثالث ووجدهم يصنعون هكذا، فطوبى لأولئك العبيد. وهذا اعلموه: أنه لو كان رب البيت يعلم في أية ساعة يأتي السارق، لكان يسهر ولا يدع بيته يُنقب. فكونوا أنتم أيضا مستعدين. فإنه في ساعة لا تعرفونها يأتي ابن الإنسان.
فقال له بطرس: يا رب ألنا قلتَ هذا أم قلته للجميع ؟ فقال الرب: من هو الوكيل الأمين الحكيم الذي يقيمه سيده على عبيده ليعطيهم طعامهم في حينه ؟ طوبى لذلك العبد الذي إذا جاء سيده يجده يفعل هكذا. حقا أقول لكم إنه يقيمه على جميع أمواله. ولكن إن قال ذلك العبد الرديء في قلبه إن سيدي يبطئ في قدومه، فيبدأ يضرب العبيد والإماء ويأكل ويشرب ويسكر، يأتي سيد ذلك العبد في اليوم الذي لا يتوقعه وفي الساعة التي لا يعرفها، فيشقه من وسطه، ويجعل نصيبه مع عديمي الإيمان (والمجد لله دائما)$agpeya$),
  (15, $agpeya$القطع$agpeya$, $agpeya$بعين متحننة يا رب انظر إلى ضعفى، فعما قليل تفنى حياتي، وبأعمالي ليس لي خلاص. فلهذا أسال: بعين رحيمة يا رب انظر إلى ضعفى وذلي ومسكنتي وغربتي، ونجني. (ذوكصابتري كيه إيو كي آجيو ابنيفماتي - المجد للآب والابن والروح القدس).
بما أن الديان حاضر، اهتمي يا نفسي وتيقظي وتفهمي تلك الساعة المخوفة. فإنه ليس رحمة في الدينونة لمن لم يستعمل الرحمة. فلهذا أشفق عليّ أيها المخلص، فإنك أنت هو محب البشر وحدك (كي نين، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين - الآن وكل أوان وإلى دهر الداهرين آمين).
يا باب الحياة العقلي، يا والدة الإله المكرمة، خلصي الذين التجأوا إليك بإيمان من الشدائد، لكي نمجد ميلادك الطاهر في كل شيء من أجل خلاص نفوسنا. (كي نين، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين - الآن وكل أوان وإلى دهر الداهرين آمين).
أيها الملك السمائي المعزى، روح الحق، الحاضر في كل مكان والمالئ الكل، كنز الصالحات، ومعطى الحياة، هلم تفضل وحل فينا، وطهرنا من كل دنس أيها الصالح، وخلص نفوسنا. (ذوكصابتري كيه إيو كي آجيو ابنيفماتي - المجد للآب والابن والروح القدس).
كما كنت مع تلاميذك أيها المخلص وأعطيتهم السلام، هلم أيضا كن معنا وامنحنا سلامك وخلصنا ونج نفوسنا. (كي نين، كي آ إي، كي ايستوس إي أوناس تون إي أونون آمين - الآن وكل أوان وإلى دهر الداهرين آمين).
إذا ما وقفنا في هيكلك المقدس نحسب كالقيام في السماء. يا والدة الإله، أنت هي باب السماء، افتحي لنا باب الرحمة.
كيريى ليسون 41 مرة$agpeya$),
  (16, $agpeya$الثلاث تقديسات$agpeya$, $agpeya$قدوس الله، قدوس القوى، قدوس الحي الذي لا يموت، الذي ولد من العذراء، ارحمنا. قدوس الله، قدوس القوى، قدوس الحي الذي لا يموت، الذي صلب عنا، ارحمنا. قدوس الله، قدوس القوى، قدوس الحي الذي لا يموت، الذي قام من الأموات وصعد إلى السموات، ارحمنا. المجد للآب والابن والروح القدس، الآن وكل أوان وإلى دهر الدهور. أمين. أيها الثالوث القدوس ارحمنا. أيها الثالوث القدوس ارحمنا. أيها الثالوث القدوس ارحمنا.
يا رب اغفر لنا خطايانا. يا رب اغفر لنا آثامنا. يا رب اغفر لنا زلاتنا. يا رب افتقد مرضى شعبك، اشفهم من أجل اسمك القدوس. آباؤنا وإخوتنا الذين رقدوا، يا رب نيح نفوسهم. يا من هو بلا خطية، يا رب ارحمنا. يا من بلا خطية، يا رب أعنا، واقبل طلباتنا إليك. لأن لك المجد والعزة والتقديس المثلث. يا رب ارحم. يا رب ارحم يا رب بارك. أمين.
واجعلنا مستحقين أن نقول بشكر: أبانا الذي في السموات....$agpeya$),
  (17, $agpeya$فصل من إنجيل لوقا ص2: 29-32$agpeya$, $agpeya$الآن يا سيدي، تطلق عبدك بسلام حسب قولك، لأن عيني قد أبصرتا خلاصك الذي أعددته قدام جميع الشعوب. نورًا تجلى للأمم، ومجدا لشعبك إسرائيل. والمجد لله دائما.$agpeya$),
  (18, $agpeya$قانون الإيمان المقدس الأرثوذكسي$agpeya$, $agpeya$بالحقيقة نؤمن بإله واحد، الله الآب، ضابط الكل، خالق السماء والأرض، ما يُرَى وما لا يرى.
نؤمن برب واحد يسوع المسيح، ابن الله الوحيد، المولود من الآب قبل كل الدهور، نور من نور، إله حق من إله حق، مولود غير مخلوق، مساو للآب في الجوهر، الذي به كان كل شيء. هذا الذي من أجلنا نحن البشر، ومن أجل خلاصنا، نزل من السماء، وتجسد من الروح القدس ومن مريم العذراء، وتأنس. وصلب عنا على عهد بيلاطس البنطي. وتألم وقبر وقام من بين الأموات في اليوم الثالث كما في الكتب، وصعد إلى السموات، وجلس عن يمين أبيه، وأيضا يأتي في مجده ليدين الأحياء والأموات، الذي ليس لملكه انقضاء.
نعم نؤمن بالروح القدس، الرب المحيى المنبثق من الآب. نسجد له ونمجده مع الآب والابن، الناطق في الأنبياء.
وبكنيسة واحدة مقدسة جامعة رسولية.
ونعترف بمعمودية واحدة لمغفرة الخطايا.
وننتظر قيامة الأموات وحياة الدهر الآتي. أمين.
كيرياليسون (يا رب ارحم) 41 مرة$agpeya$),
  (19, $agpeya$قدوس قدوس قدوس$agpeya$, $agpeya$قدوس، قدوس، قدوس، رب الصباؤوت. السماء والأرض مملوءتان من مجدك وكرامتك. ارحمنا يا الله الآب ضابط الكل. أيها الثالوث القدوس ارحمنا. أيها الرب إله القوات كن معنا، لأنه ليس لنا معين في شدائدنا وضيقاتنا سواك.
حل واغفر واصفح لنا يا الله عن سيئاتنا، التي صنعناها بإرادتنا والتي صنعناها بغير إرادتنا، التي فعلناها بمعرفة والتي فعلناها بغير معرفة، الخفية والظاهرة. يا رب اغفرها لنا، من أجل اسمك القدوس الذي دعي علينا. كرحمتك يا رب وليس كخطايانا.
واجعلنا مستحقين أن نقول بشكر: أبانا الذي في السموات..$agpeya$),
  (20, $agpeya$التحليل$agpeya$, $agpeya$أيها السيد الرب يسوع المسيح، ابن الله الحي الأزلي، أنر عقولنا لنفهم أقوالك المحيية. وأنهضنا من ظلمة الخطية القاتلة للنفس. واجعلنا أهلا أن نكون مستقيمين في عمل الخير. وفى وقت مجيئك لتدين العالم، فلنستحق سماع ذلك الصوت المملوء فرحا، القائل: تعالوا إلى يا مبارَكي أبى، رثوا الملك المعد لكم من قبل إنشاء العالم. نعم يا رب، سهل لنا أن نكون في تلك الساعة بغير خوف ولا اضطراب ولا سقوط في الدينونة. ولا تجازنا من أجل كثرة آثامنا، لأنك وحدك المتحنن الطويل الأناة الكثير الرحمة، بشفاعة سيدتنا والدة الإله القديسة مريم، وشفاعة جميع مصاف قديسيك. أمين.$agpeya$),
  (21, $agpeya$طلبة تصلى آخر كل ساعة$agpeya$, $agpeya$ارحمنا يا الله ثم ارحمنا. يا من في كل وقت وكل ساعة، في السماء وعلى الأرض، مسجود له وممجد. المسيح إلهنا الصالح، الطويل الروح، الكثير الرحمة، الجزيل التحنن، الذي يحب الصديقين ويرحم الخطاة الذين أولهم أنا. الذي لا يشاء موت الخاطئ مثل ما يرجع ويحيا. الداعي الكل إلى الخلاص لأجل الموعد بالخيرات المنتظرة.
يا رب اقبل منا في هذه الساعة وكل ساعة طلباتنا. سهل حياتنا، وأرشدنا إلى العمل بوصاياك. قدس أرواحنا. طهر أجسامنا. قوم أفكارنا. نق نياتنا. اشف أمراضنا واغفر خطايانا. ونجنا من كل حزن رديء ووجع قلب. أحطنا بملائكتك القديسين، لكي نكون بمعسكرهم محفوظين ومرشدين، لنصل إلى اتحاد الإيمان وإلى معرفة مجدك غير المحسوس وغير المحدود، فإنك مبارك إلى الأبد. أمين.$agpeya$),
  (22, $agpeya$التحليل الكبير لنصف الليل$agpeya$, $agpeya$نسألك ونشكرك، أيها السيد الرب يسوع المسيح، ابن الله الحي الأزلي، الكائن في النور قبل كل الدهور، نور من نور:
أنر يا رب عقولنا وقلوبنا، وأضيء أفهامنا، لنفهم كلامك المحيي. وأقمنا من ظلمة الخطية القاتلة للنفس. واجعلنا مستحقين أن نكون مستقيمين في عمل الخير والصلاح. وفي وقت مجيئك الثاني المرهوب، لتدين فيه العالم، فلنستحق سماع ذلك الصوت المملوء فرحا وبهجة، وعزاء وسرورا، ونعيما من فمك الإلهي القائل: "تعالوا إلي يا مبارَكي أبي، رثوا الملك المعد لكم قبل إنشاء العالم". نعم أيها الرب إلهنا: وفقنا أن نكون في ذلك اليوم، وتلك الساعة، بغير خوف ولا عيب ولا انزعاج، ولا سقوط ولا انحراف. ولا تؤاخذنا يا رب بكثرة آثامنا. اصفح يا رب عن جميع سيئاتنا وزلاتنا، وغلطاتنا وهفواتنا.
وارفع يا رب عنا وعن جميع العالم، الموت والغلاء، والوباء والفناء، والجلاء وسيف الأعداء، ومؤامرة الشياطين، وشر الحريق والغرق، ومقاومة الأشرار وكيد الفجار، وجور السلطان. وأبطل مؤامرة المعاندين لنا.
اللهم إنك ربنا وإلهنا، تراءف علينا، ولا تطرحنا في بحار المهالك ولا عقاب المسالك. لكن نجنا واحفظنا واسترنا. وأنهضنا من الملل والضجر والتواني والكسل. ولا تدع العدو الشيطان يطغينا بوسع الأمل. بل نبه عقولنا، وأيقظ قلوبنا من نوم الغفلة وتسويف العمر باطلا. اللهم اترك آثامنا واصفح عن زلاتنا. ولا تذكر خطايانا ولا سيئاتنا، ولا تغضب علينا ولا يدم غضبك إلى الأبد. ارحمنا يا رب ثم ارحمنا، فإننا ضعفاء ومساكين، وفي بحار الخطايا غارقين. فإليك نصرخ ولك نسجد وبك نعترف وإليك نرغب. لا تقطع رجاءنا يا سيدي من رحمتك، ولا تغلق باب رحمتك في وجوهنا. بل بفضلك خلصنا، وإلى رحمتك وفقنا، وصوتك الفرح أسمعنا.
اللهم طهرنا وطهر قلوبنا من الأفكار الخبيثة، النجسة الرديئة. وأبطل عنا يا رب وعن كل شعبك، كل الأحلام والخيالات، والهواجس الشيطانية. أقمنا يا الله من كل سقطة وبلية. ثبت فينا يا الله الصبر والرجاء والمحبة والإيمان الأرثوذكسي. واحسبنا من خرافك اليمينية. وأجلسنا مع الذين يتكئون في وليمتك السمائية. واغفر لنا كل إثم وذنب وخطية. وحصّنا بحصن جنود ملائكتك النورانية. فإنه ليس لنا خلاص إلا برحمتك واتكالنا عليك، وإيماننا بك. ورجائنا فيك.
اقبل منا يا رب دعاءنا في هذا الوقت الحاضر، وكل الأوقات. وكل الذين أمرونا وأوصونا أن نذكرهم في الصلوات والقداسات والقناديل والتذكارات، الأحياء منهم والأموات. اذكرنا يا رب نحن وإياهم بالصالحات، في أورشليم السمائية، في ملكوت السموات.
امح يا رب سيئاتنا والذين أساءوا إلينا اترك لهم ولنا. برحمتك يا رب خلص نفوسنا أجمعين. يا رب خلص شعبك. بارك ميراثك. ارعهم وسسهم إلى الأبد. خلص الذين في الشدائد، والضيقات والأحزان. حل المأسورين من رباط الشياطين. أشبع الجياع من الخيرات. عزِّ صغيري القلوب والنفوس. أقم الساقطين. ثبت القائمين. رد الضالين، عل الأرامل والأيتام، أسعف المعوزين. أعطِ بركة لثمار الأرض، مزاجا طيبا للهواء، نموا للأشجار، صعودا كاملا لمياه الأنهار، بارك في الندى والأمطار. أعط قناعة للمحتاجين. أوف عن المديونين. اجمع شتات المتفرقين، اقبل توبة التائبين، اقبل اعتراف المعترفين. أعط فهما للموعوظين. احكم يا رب للمظلومين .
املأ قلوبنا فرحا وبهجة وعزاء وسرورا ونعيما لكي ما إذا نلنا كفافنا في كل شيء، نتناهى في الأعمال الصالحة المرضية. بارك يا رب في الغلات بالبركات السمائية. بارك يا رب إكليل هذه السنة بصلاحك. بارك يا رب الباذر والزارع، والغارس والحاصد، كما باركت لبني إسرائيل في غلات العام السادس.
بارك يا رب في اجتماعنا هذا، وكل اجتماع الشعوب الأرثوذكسيين. واحفظ لنا وعلينا، حياة وقيام أبينا السيد الأب البطريرك أنبا.. ..، بطريرك هذا الزمان، خلصه يا رب وخلص شعبه من جميع البلايا والتجارب والأحزان. وكذلك شركاءه في الخدمة الرسولية. آباءنا المطارنة، وآباءنا الأساقفة، وآباءنا القمامصة وآباءنا القسوس، وإخوتنا الشمامسة وآباءنا الرهبان، وإخوتنا العلمانيين، والذين أتوا وحضروا واشتركوا معنا في هذه الصلاة. وكل صلوات الأرثوذكسيين الآن طالبين مغفرة خطاياهم، ورحمة لنفوسهم، باركنا وباركهم، حاللنا وحاللهم، اغفر خطايانا وخطاياهم، الماضية والمستأنفة، الذاتية وغير الذاتية، الليلة والنهارية، الظاهرة والخفية.
أدم يا رب عمار المجامع، والكنائس المقدسة، والبراري الأرثوذكسية، والشيوخ الساكنين فيها، وخدامها ومدبريها، ومن بها، واجعل الأمن والسلام والطمأنينة بينهم. وأخضع العدو الشرير تحت أقدامنا وأقدامهم. ولا تجعل له فينا ولا فيهم نصيبا، لا بضربة شمال ولا بضربة يمين. واحفظهم بيدك العالية وذراعك الحصينة. نجنا يا سيدي من التجارب الرديئة، والأشراك المنصوبة المرئية وغير المرئية.
اذكر يا رب آباءنا وأمهاتنا واخوتنا، وأهلنا وأقاربنا ومعلمينا، وأولادنا الروحيين (والجسديين)، وسائر بني المعمودية أجمعين. اذكر يا رب الذين لهم معنا تعب وشركة. اذكر يا رب الذين أكلنا وشربنا من كدهم وتعبهم، وآوونا في منازلهم. وأعطونا من أيديهم. عوضهم يا رب عوض الفانيات بالباقيات، والأرضيات بالسمائيات. املأ بيوتهم ومخازنهم من كل الخيرات، عوضهم يا رب عوض الواحد، ثلاثين وستين ومائة، وغفران خطاياهم في ملكوت السموات. اذكر يا رب الذين أحسنوا إلينا وإلى إخوتنا المساكين، بجميع وجوه الحسنات. محبة فيك وإكراما لاسمك القدوس، باركهم.
اذكر يا رب المهتمين بالصعائد والقرابين والمحرقات والخمر والزيت، والبكور والبخور، والستور والنذور وكتب القراءة وكل أواني المذبح جميعا. عوضهم يا رب عن عطاياهم بغفران خطاياهم. وهب لهم في هذا الدهر الحاضر الحياة الهنيئة وفي الدهر الآتي الحياة الأبدية.
اذكر يا رب آباءنا وإخوتنا الذين سبقوا فرقدوا وتنيحوا في الإيمان المستقيم بالمسيح. نيح يا رب نفوسهم أجمعين، في أحضان آبائنا القديسين إبراهيم وإسحق ويعقوب، في كورة الأحياء، في فردوس النعيم. أما نحن الأحياء فأعنا على خلاص نفوسنا، ودبر حياتنا حسب إرادتك الصالحة.
تفضل يا رب اذكر حقارتي وذلي وضعفي، أنا الخاطئ الشقي غير المستحق الوقوف بين يديك من أجل كثرة خطاياي وذنوبي، لا ترذلني. أقم يا رب قرن خلاص شعبك بإشارة صليبك المحيي. فرجك يا رب عند الشدة وعونك يا رب عند الكرب والذلة. خلصنا يا رب وخلص كل من في شدة. ومرضى شعبك اشفهم.
واجعل يا رب شعبك المسيحيين الحاضرين معنا والغائبين عنا، أن يكونوا مباركين محاللين من فمك الإلهي. من مشارق الشمس إلى مغاربها ومن الشمال إلى اليمين. واقبلنا إليك كما قبلت اللص اليمين، وأنت على خشبة الصليب، ووهبت له فردوس النعيم .
اذكر يا رب الأيتام والأرامل، والمنقطعين والعاجزين، والذين ليس لهم أحد يذكرهم. اذكرنا يا رب نحن وإياهم في أورشليم السمائية. اذكر يا رب القائمين والقاعدين، والراقدين والمطروحين، والمسافرين في البر والبحر والهواء، والسهل والوعر والأودية، والطرقات ورؤوس الجبال، والتلال والمغاير. والذين في المطابق والسجون، والذين في السبي والنفي، والمأسورين والمربوطين برباط السلاطين والشياطين. ردهم وأت بهم الجميع إلى الميناء، سالمين غانمين، كاسبين رابحين، معافي النفس والجسد والروح.
واجعل يا ربي يسوع المسيح صلاتنا هذه أن تكون مقبولة أمامك بغير رياء ولا كبرياء، ولا عظمة ولا افتخار ولا عيب. أعنا يا الله على رضاك. أعنا على العمل بوصاياك. أعنا على سكرات الموت وما قبل الموت وما بعد الموت. لأنك أنت إله صالح طويل الروح، كثير الرحمة والتحنن. اللهم اجعل باب بيعتك مفتوحا أمام وجوهنا على ممر الدهور والأزمان، وإلى آخر كل زمان. ارحمنا يا الله كعظيم رحمتك.
بشفاعات ذات الشفاعات، معدن الطهر والجود والبركات، سيدتنا كلنا، وفخر جنسنا، العذراء البتول الزكية القديسة مريم، والشهيد المكرم مار مرقس الإنجيلي الرسول كاروز الديار المصرية، وكافة الملائكة والآباء والأنبياء، والرسل والشهداء والقديسين والسواح والعباد، والنساك المجاهدين، والذين أرضوا الرب بأعمالهم الصالحة منذ آدم إلى آخر الدهور.
ولك نسجد أيها الثالوث القدوس الاب والإبن والروح القدس الآن وكل أوان وإلى دهر الداهرين أمين.
اللهم اجعلنا مستحقين أن نقول بشكر: أبانا الذي في السموات...$agpeya$)
) as v(sort_order, title_ar, body_ar)
